import React from "react";
import { cn } from "@/lib/utils";

export type ProviderBrandKey =
  | "eostage"
  | "openai"
  | "anthropic"
  | "claude"
  | "google-gemini"
  | "deepseek"
  | "moonshot-kimi"
  | "minimax"
  | "zhipu-glm"
  | "aliyun-bailian"
  | "openrouter"
  | "xai-grok"
  | "github-copilot"
  | "custom";

function resolveFromText(hay: string): ProviderBrandKey | null {
  if (!hay) return null;
  if (hay.includes("eostage")) return "eostage";
  if (hay.includes("openrouter")) return "openrouter";
  if (hay.includes("copilot") || hay.includes("github")) return "github-copilot";
  if (
    hay.includes("gemini") ||
    hay.includes("googleapis") ||
    hay.includes("generativelanguage") ||
    hay.includes("google")
  ) {
    return "google-gemini";
  }
  if (hay.includes("claude")) return "claude";
  if (hay.includes("anthropic")) return "anthropic";
  if (hay.includes("deepseek")) return "deepseek";
  if (hay.includes("kimi") || hay.includes("moonshot")) return "moonshot-kimi";
  if (hay.includes("minimax")) return "minimax";
  if (
    hay.includes("zhipu") ||
    hay.includes("bigmodel") ||
    hay.includes("z.ai") ||
    hay === "glm" ||
    hay.includes("zhipu-glm")
  ) {
    return "zhipu-glm";
  }
  if (
    hay.includes("bailian") ||
    hay.includes("aliyun") ||
    hay.includes("dashscope") ||
    hay.includes("qwen")
  ) {
    return "aliyun-bailian";
  }
  if (hay.includes("grok") || hay.includes("x.ai") || hay.includes("xai")) {
    return "xai-grok";
  }
  if (
    hay.includes("openai") ||
    hay.includes("codex") ||
    hay.includes("chatgpt") ||
    /(?:^|[^a-z0-9])gpt-[a-z0-9]/i.test(hay)
  ) {
    return "openai";
  }
  return null;
}

function normalizeBaseUrlForBrand(baseUrl?: string | null): string {
  const raw = (baseUrl ?? "").trim().toLowerCase();
  if (!raw) return "";
  const stripped = raw
    .replace(/\/v1beta\/openai(?:\/.*)?$/, "")
    .replace(/\/compatible-mode(?:\/.*)?$/, "");
  try {
    const u = new URL(stripped.includes("://") ? stripped : `https://${stripped}`);
    return u.hostname || stripped;
  } catch {
    return stripped;
  }
}

export function resolveProviderBrandKey(
  idOrName?: string | null,
  baseUrl?: string | null,
  _modelHint?: string | null
): ProviderBrandKey {
  const byName = resolveFromText((idOrName ?? "").toLowerCase());
  if (byName) return byName;

  const byHost = resolveFromText(normalizeBaseUrlForBrand(baseUrl));
  if (byHost) return byHost;

  return "custom";
}

export interface ProviderBrandLogoProps {
  provider?: string | null;
  baseUrl?: string | null;
  modelHint?: string | null;
  className?: string;
}

